CREATE DATABASE IF NOT EXISTS household_db CHARACTER SET utf8mb4;
USE household_db;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,fullname VARCHAR(120) NOT NULL,role ENUM('admin','worker','official') NOT NULL);
CREATE TABLE IF NOT EXISTS settings(k VARCHAR(40) PRIMARY KEY,v VARCHAR(100) NOT NULL);
INSERT IGNORE INTO settings VALUES('poverty_pc','2871.17'),('food_pc','2000');
CREATE TABLE IF NOT EXISTS households(id INT AUTO_INCREMENT PRIMARY KEY,brgy VARCHAR(100) NOT NULL,interview_date DATE NULL,ln VARCHAR(80) NOT NULL,fn VARCHAR(80) NOT NULL,mn VARCHAR(80),age INT NULL,sex VARCHAR(10),birthdate DATE NULL,civil VARCHAR(40),edu VARCHAR(80),occ VARCHAR(120),income DECIMAL(12,2) DEFAULT 0,religion VARCHAR(60),contact VARCHAR(40),total_members INT DEFAULT 1,total_families INT DEFAULT 1,house_type VARCHAR(20),house_own VARCHAR(30),electricity VARCHAR(5),chronic VARCHAR(5),chronic_spec VARCHAR(150),philhealth VARCHAR(5),ph_no VARCHAR(40),ph_cat VARCHAR(60),s_inc TINYINT DEFAULT 0,s_emp TINYINT DEFAULT 0,s_food TINYINT DEFAULT 0,s_hou TINYINT DEFAULT 0,s_hea TINYINT DEFAULT 0,s_edu TINYINT DEFAULT 0,s_ast TINYINT DEFAULT 0,s_sup TINYINT DEFAULT 0,interviewer VARCHAR(120),household_code VARCHAR(20) NULL,created_by INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(brgy),INDEX(ln,fn));
CREATE TABLE IF NOT EXISTS members(id INT AUTO_INCREMENT PRIMARY KEY,household_id INT NOT NULL,name VARCHAR(150),age INT NULL,sex VARCHAR(10),edu VARCHAR(80),occ VARCHAR(120),income DECIMAL(12,2) DEFAULT 0,remarks VARCHAR(100),FOREIGN KEY(household_id) REFERENCES households(id) ON DELETE CASCADE);

CREATE TABLE IF NOT EXISTS audit_log(id INT AUTO_INCREMENT PRIMARY KEY,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,user_id INT NULL,username VARCHAR(50),action VARCHAR(12) NOT NULL,household_id INT NULL,details VARCHAR(1000),ip VARCHAR(45),INDEX(action),INDEX(username),INDEX(household_id),INDEX(created_at));
CREATE TABLE IF NOT EXISTS dup_ignore(gkey CHAR(32) PRIMARY KEY,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
